mapper.select:
		/*deleteMasterCmClSalesTaxsheetIssueReg_ICOMGRDT*/
		SELECT AP_BILL_FLAG 
         FROM ICOMGRDT 
         WHERE AR_TAX_BILL_NO = #{TAX_BILL_NO}
            AND AP_BILL_FLAG = 'Y'

/*selectMasterCmClSalesTaxsheetIssueRegList*/
SELECT SB.KEP_IRS_NAME ,NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE ) AS ISSUE_DATE ,SB.SITE_GUBUN_NAME ,SB.BUYER_NAME ,SB.BUYER_IRS_NO ,SB.TAX_TYPE_TEXT ,SB.BILL_TYPE_TEXT ,NVL(SB.BILL_CODE, CASE WHEN MAIN.CONVERSATION_ID IS NULL THEN ( SELECT CMPY.BILL_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = SB.BUYER ) WHEN MAIN.CONVERSATION_ID IS NOT NULL THEN '41000008' ELSE '90000001' END ) AS BILL_CODE_TEXT ,SB.SUPP_PRICE ,SB.TAX_PRICE ,SB.AMT ,SB.PRINT_DATE ,SB.PRINT_CNT ,SB.TAX_BILL_NO ,SB.SEND_FLAG ,SB.SEND_DATE ,SB.CHANGE_DATE ,SB.REMARK ,SB.KEP_IRS_NO ,SB.SITE_GUBUN_CODE ,SB.DEPT_CODE ,SB.BUYER ,SB.CONFIRM_FLAG ,SB.STATUS ,SB.TOT_TAX_PRICE ,SB.PARTIAL_FLAG ,SB.CLOSE_MONTH ,SB.CLOSE_REVISION ,SB.IRS_NAME ,SB.IRS_NO ,SB.REPLACE_BUYER_IRS_NO ,SB.CEO_NAME_LOC ,SB.INDUSTRY_TYPE ,SB.BUSINESS_ITEMS ,SB.ADDRESS_LOC ,SB.E_TAX_BILL_FLAG ,SB.E_TAX_BILL_DATE ,SB.ADD_USER_ID ,REPLACE(IRS.IRS_NO,'-','') AS KEP_COM_IRS_NO ,IRS.IRS_NAME AS KEP_COM_NAME_LOC ,IRS.BUSINESS_ITEMS AS KEP_COM_BUSINESS_ITEMS ,IRS.INDUSTRY_TYPE AS KEP_COM_INDUSTRY_TYPE ,IRS.CEO_NAME_LOC AS KEP_COM_CEO_NAME_LOC ,IRS.ADDRESS_LOC AS KEP_COM_ADDRESS_LOC ,USR.FND_USER_NAME AS KEP_USER_NAME ,SB.KEP_USER_PHONE_NUMBER ,USR.EMAIL AS KEP_USER_EMAIL ,USR.SMART_ID AS SMART_ID ,USR.SMART_PASSWORD AS SMART_PASSWORD ,USR.AUTHTOKEN AS AUTHTOKEN ,NVL(NVL(SB.GR_CREATOR_EMAIL,MAIN.BYR_EMAIL), BILL.EMAIL) AS RECV_EMAIL ,NVL(NVL(SB.GR_CREATOR_NAME,MAIN.BYR_EMP_NAME),BILL.USER_NAME_LOC) AS RECV_USER_NAME ,BILL.PHONE_NUMBER AS RECV_PHONE_NUMBER ,MAIN.AMEND_CODE AS AMEND_CODE ,MAIN.CONVERSATION_ID AS CONVERSATION_ID ,MAIN.ISSUE_ID AS ISSUE_ID ,MAIN.ORI_ISSUE_ID AS ORI_ISSUE_ID ,STATUS.DTI_STATUS AS DTI_STATUS ,STATUS.RETURN_DESCRIPTION AS RETURN_DESCRIPTION ,STATUS.NTS_SEND_STATUS ,STATUS.NTS_RESULT_CODE ,STATUS.RETURN_CODE STATUS_RETURN_CODE ,#{st_user_id} AS CREATED_BY ,MAIN.CREATED_BY AS MAIN_CREATED_BY ,SB.ASK_TYPE AS AR_REQ_TYPE ,SB.ARDT_REMARK ,SB.BYR_BIZPLACE_CODE ,MAIN.SUP_AMOUNT AS MAIN_SUP_AMOUNT ,MAIN.TAX_AMOUNT AS MAIN_TAX_AMOUNT ,MAIN.TOTAL_AMOUNT AS MAIN_TOTAL_AMOUNT ,SB.E_TAX_SYSTEM_ID ,SB.EXP_CUR ,SB.EXP_CUR_PRICE ,SB.EXP_FOR_ITEM_AMT ,SB.EXP_GR_NO ,SB.EXP_DATE_OF_SHIPMENT FROM ( SELECT MAX((SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'TX01' AND CODE = AR.KEP_IRS)) AS KEP_IRS_NAME, MAX(AR.ISSUE_DATE) AS ISSUE_DATE, MAX((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = AR.SITE)) SITE_GUBUN_NAME, MAX(AR.IRS_NAME) AS BUYER_NAME, MAX(AR.IRS_NO) AS BUYER_IRS_NO, MAX(AR.TAX_TYPE) TAX_TYPE_TEXT, MAX(AR.BILL_TYPE) BILL_TYPE_TEXT, MAX(AR.TOT_SUPP_PRICE) AS SUPP_PRICE, SUM(AR.TAX_PRICE) AS TAX_PRICE, MAX(AR.TOT_AMT) AS AMT, MAX(AR.PRINT_DATE) AS PRINT_DATE, NVL(MAX(AR.PRINT_CNT),0)||'/'||NVL(MAX(AR.PRINT_AVAIL_CNT),0) AS PRINT_CNT, MAX(AR.TAX_BILL_NO) AS TAX_BILL_NO, MAX(DECODE(AR.SEND_TIME,NULL,'미전송','전송')) SEND_FLAG, MAX(AR.SEND_DATE) AS SEND_DATE, MAX(AR.CHANGE_DATE) AS CHANGE_DATE, MAX((SELECT REMARK_DESCRIPTION FROM KEPTITEM WHERE TAX_BILL_NO = AR.TAX_BILL_NO AND ITEM_SEQ = '000001')) REMARK, MAX(AR.KEP_IRS) AS KEP_IRS_NO, MAX(AR.SITE) AS SITE_GUBUN_CODE, MAX(AR.DEPT_CODE) AS DEPT_CODE, MAX(AR.BUYER_CODE) AS BUYER, MAX(AR.CONFIRM_FLAG) AS CONFIRM_FLAG, MAX(DECODE(AR.CONFIRM_FLAG,'N','미제출','Y', DECODE(AR.IF_SEND_FLAG,NULL,'제출완료','N','전송대기','E','전송에러','Y','전송완료'))) AS STATUS, MAX(AR.TOT_TAX_PRICE) AS TOT_TAX_PRICE, MAX(AR.PARTIAL_FLAG) AS PARTIAL_FLAG, MAX(AR.AR_CLOSE_MONTH) AS CLOSE_MONTH, MAX(AR.AR_CLOSE_REVISION) AS CLOSE_REVISION, MAX(IRSN.IRS_NAME) AS IRS_NAME, MAX(IRSN.IRS_NO) AS IRS_NO, REPLACE(MAX(IRSN.IRS_NO),'-','') AS REPLACE_BUYER_IRS_NO, MAX(IRSN.CEO_NAME_LOC) AS CEO_NAME_LOC, MAX(IRSN.INDUSTRY_TYPE) AS INDUSTRY_TYPE, MAX(IRSN.BUSINESS_ITEMS) AS BUSINESS_ITEMS, MAX(IRSN.ADDRESS_LOC) AS ADDRESS_LOC, MAX(AR.E_TAX_BILL_FLAG) E_TAX_BILL_FLAG, MAX(AR.E_TAX_BILL_DATE) E_TAX_BILL_DATE , MAX(AR.ADD_USER_ID) AS ADD_USER_ID , (SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID =#{st_user_id}) KEP_USER_PHONE_NUMBER , MAX(AR.SITE) AS SITE, MAX(AR.ASK_TYPE) AS ASK_TYPE , MAX(AR.REMARK) AS ARDT_REMARK, MAX(AR.BYR_BIZPLACE_CODE) AS BYR_BIZPLACE_CODE, MAX(AR.BILL_CODE) AS BILL_CODE, MAX(AR.GR_CREATOR_NAME) AS GR_CREATOR_NAME, MAX(AR.GR_CREATOR_EMAIL) AS GR_CREATOR_EMAIL, MAX(AR.E_TAX_SYSTEM_ID) AS E_TAX_SYSTEM_ID, MAX(AR.EXP_CUR) AS EXP_CUR, MAX(AR.EXP_CUR_PRICE) AS EXP_CUR_PRICE, MAX(AR.EXP_FOR_ITEM_AMT) AS EXP_FOR_ITEM_AMT, MAX(AR.EXP_GR_NO) AS EXP_GR_NO, MAX(AR.EXP_DATE_OF_SHIPMENT) AS EXP_DATE_OF_SHIPMENT FROM KEPTARDT AR,KEPTIRSN IRSN WHERE AR.BUYER_CODE = IRSN.COM_CODE(+) AND AR.IRS_NO = IRSN.IRS_NO(+) AND SUBSTR(AR.ISSUE_DATE, 0, 6) BETWEEN SUBSTR(#{st_from_date}, 0, 6) AND SUBSTR(#{st_to_date}, 0, 6) AND AR.SITE IN ('KA', 'KK') AND AR.STATUS != 'D' AND NVL(AR.AR_TYPE,'01') = '01'
AND AR.ADD_USER_ID = #{st_add_user_id}
AND AR.TAX_BILL_NO LIKE #{st_tax_bill_no}||'%'
AND AR.BILL_TYPE = #{st_bill_type_text}
AND (SELECT BILL_CODE FROM ICOMCMPY WHERE COM_CODE = AR.BUYER_CODE) = #{st_bill_code_text}
AND AR.BUYER_CODE = #{st_buyer_code}
AND AR.IRS_NO LIKE '%'||#{st_buyer_irs_no}||'%'
AND AR.CONFIRM_FLAG = #{st_confirm_flag}
AND DECODE(AR.SEND_DATE,NULL,'N','Y') = #{st_send_flag}
AND AR.DEPT_CODE = #{st_user_dept}
GROUP BY AR.TAX_BILL_NO ) SB, KEPTIRSN IRS, XXSB_DTI_SM_USER USR, XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS, BILL_ACCOUNTING BILL WHERE SB.KEP_IRS_NO = IRS.IRS_NO AND NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE) BETWEEN #{st_from_date} AND #{st_to_date} AND SB.SITE = IRS.SITE AND IRS.COM_CODE = 'KRKORE0001' AND REPLACE(SB.KEP_IRS_NO,'-','') = USR.FND_REGNO(+) AND USR.FND_USER (+)= #{st_user_id} AND SB.TAX_BILL_NO = MAIN.SEQ_ID(+) AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID(+) AND SB.BUYER = BILL.COM_CODE (+) AND BILL.PRIORITY (+)= 'Y' AND MAIN.STATUS (+)!= 'D' AND SB.BUYER_IRS_NO = BILL.IRS_NO (+)
AND STATUS.DTI_STATUS = #{st_dti_status}
AND STATUS.NTS_SEND_STATUS = #{st_ntd_sendstatus}
AND MAIN.CONVERSATION_ID IS NULL
AND NVL(NVL(SB.GR_CREATOR_NAME,MAIN.BYR_EMP_NAME),BILL.USER_NAME_LOC) LIKE #{st_recv_user_nm}||'%'
ORDER BY SB.BUYER_NAME ,SB.TAX_BILL_NO, MAIN.CONVERSATION_ID, NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE )

/*selectMasterCmClSalesTaxsheetIssueRegList_Detail*/
SELECT SB.KEP_IRS_NAME ,NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE ) AS ISSUE_DATE ,SB.SITE_GUBUN_NAME ,SB.BUYER_NAME ,SB.BUYER_IRS_NO ,SB.TAX_TYPE_TEXT ,SB.BILL_TYPE_TEXT ,CASE WHEN MAIN.CONVERSATION_ID IS NULL THEN ( SELECT CMPY.BILL_CODE FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = SB.BUYER ) WHEN MAIN.CONVERSATION_ID IS NOT NULL THEN '41000008' ELSE '90000001' END AS BILL_CODE_TEXT ,SB.TOT_SUPP_PRICE AS SUPP_PRICE ,SB.TOT_TAX_PRICE AS TAX_PRICE ,SB.TOT_AMT AS AMT ,SB.DEPT_NAME ,SB.SUPP_PRICE AS DEPT_SUPP_PRICE ,SB.TAX_PRICE AS DEPT_TAX_PRICE ,SB.AMT AS DEPT_AMT ,SB.PRINT_DATE ,SB.PRINT_CNT ,SB.TAX_BILL_NO ,SB.SEND_FLAG ,SB.SEND_DATE ,SB.CHANGE_DATE ,SB.REMARK ,SB.KEP_IRS_NO ,SB.SITE_GUBUN_CODE ,SB.DEPT_CODE ,SB.BUYER ,SB.CONFIRM_FLAG ,SB.STATUS ,SB.PARTIAL_FLAG ,SB.CLOSE_MONTH ,SB.CLOSE_REVISION ,SB.IRS_NAME ,SB.IRS_NO ,SB.REPLACE_BUYER_IRS_NO ,SB.CEO_NAME_LOC ,SB.INDUSTRY_TYPE ,SB.BUSINESS_ITEMS ,SB.ADDRESS_LOC ,SB.E_TAX_BILL_FLAG ,SB.E_TAX_BILL_DATE ,SB.ADD_USER_ID ,REPLACE(IRS.IRS_NO,'-','') AS KEP_COM_IRS_NO ,IRS.IRS_NAME AS KEP_COM_NAME_LOC ,IRS.BUSINESS_ITEMS AS KEP_COM_BUSINESS_ITEMS ,IRS.INDUSTRY_TYPE AS KEP_COM_INDUSTRY_TYPE ,IRS.CEO_NAME_LOC AS KEP_COM_CEO_NAME_LOC ,IRS.ADDRESS_LOC AS KEP_COM_ADDRESS_LOC ,USR.FND_USER_NAME AS KEP_USER_NAME ,SB.KEP_USER_PHONE_NUMBER ,USR.EMAIL AS KEP_USER_EMAIL ,USR.SMART_ID AS SMART_ID ,USR.SMART_PASSWORD AS SMART_PASSWORD ,USR.AUTHTOKEN AS AUTHTOKEN ,NVL(NVL(SB.GR_CREATOR_EMAIL,MAIN.BYR_EMAIL), BILL.EMAIL) AS RECV_EMAIL ,NVL(NVL(SB.GR_CREATOR_NAME,MAIN.BYR_EMP_NAME),BILL.USER_NAME_LOC) AS RECV_USER_NAME ,BILL.PHONE_NUMBER AS RECV_PHONE_NUMBER ,MAIN.AMEND_CODE AS AMEND_CODE ,MAIN.CONVERSATION_ID AS CONVERSATION_ID ,MAIN.ISSUE_ID AS ISSUE_ID ,MAIN.ORI_ISSUE_ID AS ORI_ISSUE_ID ,STATUS.DTI_STATUS AS DTI_STATUS ,STATUS.RETURN_DESCRIPTION AS RETURN_DESCRIPTION ,STATUS.NTS_SEND_STATUS ,STATUS.NTS_RESULT_CODE ,STATUS.RETURN_CODE STATUS_RETURN_CODE ,#{st_user_id} AS CREATED_BY ,MAIN.CREATED_BY AS MAIN_CREATED_BY ,SB.ASK_TYPE AS AR_REQ_TYPE ,SB.ARDT_REMARK ,SB.BYR_BIZPLACE_CODE ,MAIN.SUP_AMOUNT AS MAIN_SUP_AMOUNT ,MAIN.TAX_AMOUNT AS MAIN_TAX_AMOUNT ,MAIN.TOTAL_AMOUNT AS MAIN_TOTAL_AMOUNT FROM ( SELECT (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'TX01' AND CODE = AR.KEP_IRS) AS KEP_IRS_NAME, AR.ISSUE_DATE AS ISSUE_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = AR.SITE) SITE_GUBUN_NAME, AR.IRS_NAME AS BUYER_NAME, AR.IRS_NO AS BUYER_IRS_NO, AR.TAX_TYPE TAX_TYPE_TEXT, AR.BILL_TYPE BILL_TYPE_TEXT, AR.TOT_SUPP_PRICE, AR.TOT_TAX_PRICE, AR.TOT_AMT, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE ='TX06' AND CODE = AR.DEPT_CODE) DEPT_NAME, AR.SUPP_PRICE, AR.TAX_PRICE, AR.AMT, AR.PRINT_DATE AS PRINT_DATE, NVL(AR.PRINT_CNT,0)||'/'||NVL(AR.PRINT_AVAIL_CNT,0) AS PRINT_CNT, AR.TAX_BILL_NO AS TAX_BILL_NO, DECODE(AR.SEND_TIME,NULL,'미전송','전송') SEND_FLAG, AR.SEND_DATE AS SEND_DATE, AR.CHANGE_DATE AS CHANGE_DATE, (SELECT REMARK_DESCRIPTION FROM KEPTITEM WHERE TAX_BILL_NO = AR.TAX_BILL_NO AND ITEM_SEQ = '000001') REMARK, AR.KEP_IRS AS KEP_IRS_NO, AR.SITE AS SITE_GUBUN_CODE, AR.DEPT_CODE AS DEPT_CODE, AR.BUYER_CODE AS BUYER, AR.CONFIRM_FLAG AS CONFIRM_FLAG, DECODE(AR.CONFIRM_FLAG,'N','미확정','Y', DECODE(AR.IF_SEND_FLAG,NULL,'확정','N','전송대기','E','전송에러','Y','전송완료')) AS STATUS, AR.PARTIAL_FLAG AS PARTIAL_FLAG, AR.AR_CLOSE_MONTH AS CLOSE_MONTH, AR.AR_CLOSE_REVISION AS CLOSE_REVISION, IRSN.IRS_NAME AS IRS_NAME, IRSN.IRS_NO AS IRS_NO, REPLACE(IRSN.IRS_NO,'-','') AS REPLACE_BUYER_IRS_NO, IRSN.CEO_NAME_LOC AS CEO_NAME_LOC, IRSN.INDUSTRY_TYPE AS INDUSTRY_TYPE, IRSN.BUSINESS_ITEMS AS BUSINESS_ITEMS, IRSN.ADDRESS_LOC AS ADDRESS_LOC, AR.E_TAX_BILL_FLAG E_TAX_BILL_FLAG, AR.E_TAX_BILL_DATE E_TAX_BILL_DATE , AR.ADD_USER_ID AS ADD_USER_ID , (SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID =#{st_user_id}) KEP_USER_PHONE_NUMBER , AR.SITE AS SITE, AR.ASK_TYPE AS ASK_TYPE , AR.REMARK AS ARDT_REMARK, AR.BYR_BIZPLACE_CODE AS BYR_BIZPLACE_CODE, AR.GR_CREATOR_NAME, AR.GR_CREATOR_EMAIL FROM KEPTARDT AR,KEPTIRSN IRSN WHERE AR.BUYER_CODE = IRSN.COM_CODE(+) AND AR.IRS_NO = IRSN.IRS_NO(+) AND SUBSTR(AR.ISSUE_DATE, 0, 6) BETWEEN SUBSTR(#{st_from_date}, 0, 6) AND SUBSTR(#{st_to_date}, 0, 6) AND AR.SITE IN ('KA', 'KK') AND AR.STATUS != 'D' AND NVL(AR.AR_TYPE,'01') = '01'
AND AR.ADD_USER_ID = #{st_add_user_id}
AND AR.TAX_BILL_NO LIKE #{st_tax_bill_no}||'%'
AND AR.BILL_TYPE = #{st_bill_type_text}
AND (SELECT BILL_CODE FROM ICOMCMPY WHERE COM_CODE = AR.BUYER_CODE) = #{st_bill_code_text}
AND AR.BUYER_CODE = #{st_buyer_code}
AND AR.IRS_NO LIKE '%'||#{st_buyer_irs_no}||'%'
AND AR.CONFIRM_FLAG = #{st_confirm_flag}
AND DECODE(AR.SEND_DATE,NULL,'N','Y') = #{st_send_flag}
AND AR.DEPT_CODE = #{st_user_dept}
) SB, KEPTIRSN IRS, XXSB_DTI_SM_USER USR, XXSB_DTI_MAIN MAIN, XXSB_DTI_STATUS STATUS, BILL_ACCOUNTING BILL WHERE SB.KEP_IRS_NO = IRS.IRS_NO AND NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE) BETWEEN #{st_from_date} AND #{st_to_date} AND SB.SITE = IRS.SITE AND IRS.COM_CODE = 'KRKORE0001' AND REPLACE(SB.KEP_IRS_NO,'-','') = USR.FND_REGNO(+) AND USR.FND_USER (+)= #{st_user_id} AND SB.TAX_BILL_NO = MAIN.SEQ_ID(+) AND MAIN.CONVERSATION_ID = STATUS.CONVERSATION_ID(+) AND SB.BUYER = BILL.COM_CODE (+) AND BILL.PRIORITY (+)= 'Y' AND MAIN.STATUS (+)!= 'D' AND SB.BUYER_IRS_NO = BILL.IRS_NO (+)
AND STATUS.DTI_STATUS = #{st_dti_status}
AND STATUS.NTS_SEND_STATUS = #{st_ntd_sendstatus}
AND MAIN.CONVERSATION_ID IS NULL
ORDER BY SB.BUYER_NAME ,SB.TAX_BILL_NO, MAIN.CONVERSATION_ID, NVL(TO_CHAR(MAIN.DTI_WDATE,'YYYYMMDD'), SB.ISSUE_DATE )

mapper.update:
/*updateMasterCmClSalesTaxsheetIssueReg_Update*/

		UPDATE
		    KEPTARDT /* 외상매출_세금계산서 */
		SET 
		    CHANGE_USER_ID  = #{st_user_id}
		  , CHANGE_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CHANGE_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
		  , ISSUE_DATE      = #{ISSUE_DATE}
		  , TAX_TYPE        = #{TAX_TYPE_TEXT}
		  , BILL_TYPE       = #{BILL_TYPE_TEXT}
		  , ASK_TYPE       =  #{AR_REQ_TYPE}
		  , REMARK =  #{ARDT_REMARK}
		  , BYR_BIZPLACE_CODE=  #{BYR_BIZPLACE_CODE}
		  , BILL_CODE = #{BILL_CODE_TEXT}
		WHERE 
		    TAX_BILL_NO     = #{TAX_BILL_NO}


		UPDATE
		    BNTKEPTARDT /* 물류비_외상매출_세금계산서 */
		SET 
		    CHANGE_USER_ID  = #{st_user_id}
		  , CHANGE_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CHANGE_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
		  , ISSUE_DATE      = #{ISSUE_DATE}
		  , BILL_TYPE       = #{BILL_TYPE_TEXT}
		WHERE 
		    TAX_BILL_NO     = #{TAX_BILL_NO}

/*deleteMasterCmClSalesTaxsheetIssueReg_Delete*/

		UPDATE KEPTARDT /* 외상매출_세금계산서 */
		SET STATUS = 'D', LEGACY_AR_NO = NULL
		WHERE 
		    TAX_BILL_NO = #{TAX_BILL_NO}


		DELETE
		    BNTKEPTARDT /* 물류비_외상매출_세금계산서 */
		WHERE 
		    TAX_BILL_NO = #{TAX_BILL_NO}

/*updateMasterCmClSalesTaxsheetIssueReg_Clear*/
UPDATE ICOMGRDT /* 구매사별 입고정보 */ SET AR_CLOSE_MONTH = '' , AR_CLOSE_REVISION = '' , AR_BILL_FLAG = 'N' , AR_TAX_BILL_NO = '' , CLOSE_USER_ID = '' WHERE 1=1 AND AR_TAX_BILL_NO = #{TAX_BILL_NO} AND STATUS <> 'D'
UPDATE BNTKEPTEXUP /* 물류비_세금계산서 업로드 임시 테이블 */ SET AR_CLOSE_MONTH = '' , AR_CLOSE_REVISION = '' , TAX_BILL_NO = '' WHERE 1=1 AND TAX_BILL_NO = #{TAX_BILL_NO}

mapper.select:
/*selectMasterCmClSalesTaxsheetIssueRegList_ARsend*/
SELECT KTDT.TAX_BILL_NO , KTDT.DEPT_CODE , KTDT.ISSUE_DATE , KTDT.IRS_NO , KTDT.BUYER_CODE , KTDT.SITE , KTDT.TOT_SUPP_PRICE , KTDT.TOT_TAX_PRICE , KTDT.TOT_AMT , KTDT.SUPP_PRICE , KTDT.TAX_PRICE , KTDT.AMT , KTDT.TAX_TYPE /* 세무구분 */ , KTDT.BILL_TYPE /* 발행조건 */ , KTDT.REMARK_DESCRIPTION , KTDT.PAY_TYPE /* 결제유형 */ , KTDT.PAY_TERMS /* 결제조건 */ , V_LUSR.USER_NAME_LOC AS USER_NAME /* 전표입력자명 */ , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'TX06' AND CODE = V_LUSR.DEPARTMENT) AS DEPT_NAME /* 전표입력자부서명 */ /*, (SELECT MAX(TRIM(EMAIL)) FROM BILL_ACCOUNTING WHERE COM_CODE = KTDT.BUYER_CODE AND IRS_NO = KTDT.IRS_NO ) AS EMAIL*/ FROM
KEPTARDT KTDT /* 외상매출_세금계산서 */
BNTKEPTARDT KTDT /* 물류비_외상매출_세금계산서 */
, V_VOC_ICOMLUSR V_LUSR /* (ICOMLUSR - 사용자정보, kepcour01@kepcon) */ WHERE 1=1 AND KTDT.ADD_USER_ID = V_LUSR.USER_ID AND KTDT.TAX_BILL_NO = #{TAX_BILL_NO}

/*selectMasterCmClSalesTaxsheetIssueRegList_KUNNR_LIFNR*/
SELECT S.SAP_CODE FROM ( SELECT SAP_CODE FROM ICOMCMPY /* 회원사정보 */ WHERE 1=1 AND BUSINESS_COND = #{BUSINESS_COND} AND STATUS IN ('C', 'R') AND IRS_NO = #{IRS_NO}
UNION
SELECT A.SAP_CODE FROM KEPTIRSN A /* 고객사 사업자정보 */ , ICOMCMPY B /* 회원사정보 */ WHERE 1=1 AND A.COM_CODE = B.COM_CODE AND A.IRS_NO = #{IRS_NO} AND B.BUSINESS_COND = #{BUSINESS_COND} AND B.STATUS IN ('C', 'R') ) S

